from typing import Any, Dict, List, Optional

from rasa.core.actions.action import Action
from rasa.core.channels import OutputChannel
from rasa.core.nlg import NaturalLanguageGenerator
from rasa.dialogue_understanding.patterns.session_end import FLOW_PATTERN_SESSION_END
from rasa.shared.core.constants import ACTION_HANGUP
from rasa.shared.core.domain import Domain
from rasa.shared.core.events import Event, SessionEnded
from rasa.shared.core.trackers import DialogueStateTracker

BOT_DISCONNECTED_REASON = "bot disconnected"
USER_DISCONNECTED_REASON = "user disconnected"


async def request_agent_hangup(
    output_channel: OutputChannel, sender_id: str
) -> List[Event]:
    """Ask the output channel to hang up and return a bot-disconnected session end.

    On voice-stream channels ``hangup`` only sets ``hangup_requested``; the call
    disconnects later when pending playback markers drain. Queued response
    deliveries are awaited first: a streamed goodbye is handed to a background
    writer, so without the wait the farewell can still be in synthesis when the
    channel tears the call down and the user never hears it.

    Args:
        output_channel: Channel that should end the conversation.
        sender_id: Conversation / recipient id passed to ``hangup``.

    Returns:
        A single ``SessionEnded`` event with ``_reason`` set to
        :data:`BOT_DISCONNECTED_REASON`.
    """
    await output_channel.wait_for_response_deliveries()
    await output_channel.hangup(sender_id)
    return [SessionEnded(metadata={"_reason": BOT_DISCONNECTED_REASON})]


class ActionHangup(Action):
    """Action which hangs up the call."""

    def name(self) -> str:
        """Return the name of the action."""
        return ACTION_HANGUP

    async def run(
        self,
        output_channel: OutputChannel,
        nlg: NaturalLanguageGenerator,
        tracker: DialogueStateTracker,
        domain: Domain,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> List[Event]:
        """Ask the output channel to hang up the call."""
        if tracker.active_flow == FLOW_PATTERN_SESSION_END:
            # Action is called from the pattern_session_end,
            # user ended the call, so we just return the SessionEnded event.
            return [SessionEnded(metadata={"_reason": USER_DISCONNECTED_REASON})]

        return await request_agent_hangup(output_channel, tracker.sender_id)
